/** Symbols use a 960 viewport whose y axis runs from -960 to 0. */
private fun symbol(name: String, pathData: String): ImageVector =
    ImageVector.Builder(name = "Symbols.$name", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
        .addGroup(translationY = 960f)
        .addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
